/* config.js — generated by backend from .env
   Backend should serve this at /static/js/config.js
   with values interpolated from environment variables.
   NEVER hardcode secrets here. Admin password is server-side only.
*/
window.SERO_CONFIG = {
    brandName:       "${SERO_BRAND_NAME}",
    brandTagline:    "${SERO_BRAND_TAGLINE}",
    brandSub:        "${SERO_BRAND_SUB}",
    description:     "${SERO_BRAND_DESCRIPTION}",

    email:           "${SERO_EMAIL}",
    phone:           "${SERO_PHONE}",
    location:        "${SERO_LOCATION}",
    instagram:       "${SERO_INSTAGRAM}",
    facebook:        "${SERO_FACEBOOK}",
    whatsapp:        "${SERO_WHATSAPP}",
    tiktok:          "${SERO_TIKTOK}",

    logoDark:        "${SERO_LOGO_DARK}",
    logoLight:       "${SERO_LOGO_LIGHT}",
    imgAbout:        "${SERO_IMG_ABOUT}",
    imgIndex:        "${SERO_IMG_INDEX}",
    imgHero:         "${SERO_IMG_HERO}",
    heroUnsplash:    "${SERO_HERO_UNSPLASH}",
    fallbackImg:     "${SERO_FALLBACK_IMG}",

    fontUrl:         "${SERO_FONT_URL}",
    fontDisplay:     "${SERO_FONT_DISPLAY}",
    fontBody:        "${SERO_FONT_BODY}",

    tailwindUrl:     "${SERO_TAILWIND_URL}",
    lucideUrl:       "${SERO_LUCIDE_URL}",

    copyrightYear:   "${SERO_COPYRIGHT_YEAR}",
    apiBase:         "${SERO_API_BASE}",
};

/* Convenience: read social links safely from config at runtime */
window.SERO_SOCIAL = {
    get facebook()  { return window.SERO_CONFIG?.facebook  || '#'; },
    get instagram() { return window.SERO_CONFIG?.instagram || '#'; },
    get whatsapp()  { return window.SERO_CONFIG?.whatsapp  || '#'; },
    get tiktok()    { return window.SERO_CONFIG?.tiktok    || '#'; },
};